sys_variable_value.value:
(function execute(inputs, outputs) {
var approvers = new x_ctans_incentnow.IncentNowUtils().getTerritoryManagers(inputs.territory);
 outputs.territory_managers="ApprovesRejectsAnyU["+approvers+"]";
 if (approvers && approvers != '') {
    outputs.count = approvers.split(',').length;
} else {
    outputs.count = 0;
}
// outputs.count = approvers && approvers.trim() !== '' ? approvers.split(',').length : 0;
//gs.info('IncentIQ Flow Action Approvers' + inputs.territory);
})(inputs, outputs);

